// The scoreboard widget's state. Unlike an alert, a score is not an event that
// plays and disappears: it is a value the overlay shows continuously, so it
// lives in a column and every change is fanned out on the same hub.
import prisma from './db';
import { publish } from './hub';
import { parseScoreConfig, type ScoreConfig } from './scoreConfig';

export type Score = { wins: number; losses: number };
/** What an overlay needs to draw the board: the tally plus its appearance. */
export type ScoreState = Score & { config: ScoreConfig };
export type ScoreTarget = 'win' | 'lose' | 'reset';

export async function getScore(userId: string): Promise<ScoreState> {
  const u = await prisma.user.findUnique({
    where: { id: userId },
    select: { wins: true, losses: true, scoreConfig: true },
  });
  return {
    wins: u?.wins ?? 0,
    losses: u?.losses ?? 0,
    config: parseScoreConfig(u?.scoreConfig),
  };
}

/** Fans the current state out untouched — used after an appearance change,
 *  which every overlay has to be told about but which moves no counter. */
export async function publishScore(userId: string): Promise<ScoreState> {
  const state = await getScore(userId);
  publish(userId, { widget: 'score', ...state });
  return state;
}

/** Applies a bounded change and fans the new score out to every overlay of
 *  this user. Counters never go below zero — a decrement at 0 is a no-op.
 *
 *  ponytail: read-then-write rather than an atomic `increment`. Ceiling: two
 *  docks clicking within the same round trip can lose one click. Upgrade path:
 *  a single `UPDATE ... SET wins = GREATEST(0, wins + $1) RETURNING *`. */
export async function adjustScore(userId: string, target: ScoreTarget, delta: number): Promise<ScoreState> {
  const cur = await getScore(userId);
  // Rebuilt field by field, never spread from `cur`: `cur` also carries the
  // config, and a spread would send it to Prisma as an unknown column.
  const next: Score =
    target === 'reset'
      ? { wins: 0, losses: 0 }
      : target === 'win'
        ? { wins: Math.max(0, cur.wins + delta), losses: cur.losses }
        : { wins: cur.wins, losses: Math.max(0, cur.losses + delta) };
  await prisma.user.update({ where: { id: userId }, data: next });
  const state: ScoreState = { ...next, config: cur.config };
  publish(userId, { widget: 'score', ...state });
  return state;
}
// The scoreboard widget's appearance. Plain module (no 'use server'), same
// shape as src/lib/alertConfig.ts: functions take userId explicitly and every
// value that reaches Prisma or the overlay is rebuilt field by field here.
import { CSS_UNSAFE } from './alertConfig';
import prisma from './db';

export const SCORE_POSITIONS = [
  'top-left',
  'top',
  'top-right',
  'center',
  'bottom-left',
  'bottom',
  'bottom-right',
] as const;
export type ScorePosition = (typeof SCORE_POSITIONS)[number];

export type ScoreConfig = {
  showLabels: boolean;
  winLabel: string;
  lossLabel: string;
  separator: string;
  winColor: string;
  lossColor: string;
  labelColor: string;
  bg: string;
  font: string;
  size: number;
  pos: ScorePosition;
};

export const SCORE_DEFAULTS: ScoreConfig = {
  showLabels: true,
  winLabel: 'WINS',
  lossLabel: 'LOSSES',
  separator: '–',
  winColor: '#31d0aa',
  lossColor: '#ff5c8a',
  labelColor: '#ffffff',
  bg: 'rgba(12,12,16,0.72)',
  font: 'system-ui, sans-serif',
  size: 64,
  pos: 'top',
};

// Labels are written with textContent, never innerHTML, so markup in them is
// inert — the cap is about layout, not safety.
const LABEL_MAX = 24;
const SEPARATOR_MAX = 4;
const SIZE_MIN = 16;
const SIZE_MAX = 200;

// Colours, `bg` and `font` are injected verbatim into the board's cssText,
// exactly like an alert card's style values, so they get the same refusal.
const COLOR_KEYS = ['winColor', 'lossColor', 'labelColor', 'bg', 'font'] as const;
const TEXT_KEYS = ['winLabel', 'lossLabel', 'separator'] as const;

export type CleanResult = { ok: true; config: ScoreConfig } | { ok: false; error: string };

/** Rebuilds a full config from untrusted input: session-form input on the way
 *  in, and a Json column that an older version may have written on the way
 *  out. Unknown keys — `userId` included — are dropped, not spread. */
export function cleanScoreConfig(raw: unknown): CleanResult {
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) {
    return { ok: false, error: 'config must be an object' };
  }
  const input = raw as Record<string, unknown>;
  const out: ScoreConfig = { ...SCORE_DEFAULTS };

  if (input.showLabels !== undefined) {
    if (typeof input.showLabels !== 'boolean') return { ok: false, error: 'showLabels must be a boolean' };
    out.showLabels = input.showLabels;
  }

  for (const k of TEXT_KEYS) {
    const v = input[k];
    if (v === undefined) continue;
    if (typeof v !== 'string') return { ok: false, error: `${k} must be a string` };
    out[k] = v.slice(0, k === 'separator' ? SEPARATOR_MAX : LABEL_MAX);
  }

  for (const k of COLOR_KEYS) {
    const v = input[k];
    if (v === undefined) continue;
    if (typeof v !== 'string') return { ok: false, error: `${k} must be a string` };
    if (CSS_UNSAFE.test(v)) {
      return { ok: false, error: `${k} contains characters that are not allowed in a style value` };
    }
    out[k] = v;
  }

  if (input.size !== undefined) {
    if (typeof input.size !== 'number' || !Number.isFinite(input.size)) {
      return { ok: false, error: 'size must be a number' };
    }
    out.size = Math.round(Math.min(SIZE_MAX, Math.max(SIZE_MIN, input.size)));
  }

  if (input.pos !== undefined) {
    const pos = SCORE_POSITIONS.find((p) => p === input.pos);
    if (!pos) return { ok: false, error: 'pos is not a known position' };
    out.pos = pos;
  }

  return { ok: true, config: out };
}

/** Read path: a stored config that fails validation (hand-edited row, a field
 *  this version no longer knows) falls back to the defaults rather than
 *  breaking the overlay. */
export function parseScoreConfig(raw: unknown): ScoreConfig {
  if (raw === null || raw === undefined) return { ...SCORE_DEFAULTS };
  const cleaned = cleanScoreConfig(raw);
  return cleaned.ok ? cleaned.config : { ...SCORE_DEFAULTS };
}

export type SaveScoreResult = { ok: true; config: ScoreConfig } | { ok: false; status: 400; error: string };

export async function saveScoreConfigFor(userId: string, raw: unknown): Promise<SaveScoreResult> {
  const cleaned = cleanScoreConfig(raw);
  if (!cleaned.ok) return { ok: false, status: 400, error: cleaned.error };
  // `where` is the session's own id and `data` is the rebuilt object — nothing
  // from the caller's body can select or write another tenant's row.
  await prisma.user.update({ where: { id: userId }, data: { scoreConfig: cleaned.config } });
  return { ok: true, config: cleaned.config };
}
// The dock's scoreboard endpoint: read the score (GET) and nudge it by one
// (POST). Deliberately as narrow as src/lib/controlFire.ts — its credential
// travels in a URL pinned in an OBS dock, so a leaked dock can move a counter
// by one per request and nothing else.
import { authorizeControl } from './control';
import { adjustScore, getScore, type ScoreTarget } from './score';

const MAX_BODY = 64 * 1024;
const TARGETS: readonly ScoreTarget[] = ['win', 'lose', 'reset'];

export async function handleControlScore(req: Request, token: string): Promise<Response> {
  let overlayId: string | undefined;

  try {
    const auth = await authorizeControl(token);
    if (auth instanceof Response) return auth;
    overlayId = auth.id;

    if (req.method === 'GET') return Response.json(await getScore(auth.userId));

    const raw = await req.text();
    if (Buffer.byteLength(raw) > MAX_BODY) {
      return Response.json({ error: 'body too large' }, { status: 413 });
    }

    let parsed: unknown;
    try {
      parsed = JSON.parse(raw);
    } catch {
      return Response.json({ error: 'invalid JSON' }, { status: 400 });
    }
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
      return Response.json({ error: 'invalid JSON' }, { status: 400 });
    }

    // Allow-list, built field by field: nothing from the body reaches the
    // database except a target drawn from TARGETS and a delta of exactly ±1.
    const { type, delta } = parsed as Record<string, unknown>;
    const target = TARGETS.find((t) => t === type);
    if (!target) {
      return Response.json({ error: 'unknown score target', known: TARGETS }, { status: 400 });
    }
    if (target !== 'reset' && delta !== 1 && delta !== -1) {
      return Response.json({ error: 'delta must be 1 or -1' }, { status: 400 });
    }

    const score = await adjustScore(auth.userId, target, target === 'reset' ? 0 : (delta as number));
    console.log(`control ${auth.id} score -> ${score.wins}-${score.losses}`);
    return Response.json(score);
  } catch (err) {
    // Never let an exception reach Next's default error handling: it may log
    // the request URL, and the URL carries the control token.
    const message = err instanceof Error ? err.message : String(err);
    console.error(overlayId ? `control ${overlayId} score error: ${message}` : `control score error: ${message}`);
    return Response.json({ error: 'internal error' }, { status: 500 });
  }
}

